    "perl -e 'system(shift)' 'echo env'",
    "python3 -c 'print(1)' env",
    "sh -c 'printf \"%s\\n\" \"$1\"' _ env",
    "bash -c 'echo \"$@\"' _ env",
    "cat < /tmp/proc/self/environment.txt",
    "cat < myproc/environ.d/x",
    "ls /proc/self/task",
    "cat < /proc/self/task/1/comm",
    "cat < /proc/sys/kernel/hostname",
    "python3 -m pytest -q",
    "node -e 'console.log(1+1)'",
    "perl -e 'print \"hi\\n\"'",
    "awk 'BEGIN{printf \"%d\\n\", 3}'",
    "ls src/*/index.ts",
    "cat < src/*/x.txt",
    "cd src && ls t*/*.test.js",
    "node --test test/**/*.test.js",
    "ls dist/*/",
    "sh -c 'echo ok'",
    "bash -c 'ls \"$@\"' _ src",
    "C=ls perl -e 'system $ENV{C}'",
    "C=env perl -e 'print $ENV{C}'",
